<template>
  <div class="create-page">
    <div class="breadcrumb"><button type="button" @click="router.push(`/teacher/course/${courseId}/assignments`)">作业管理</button><span>›</span><strong>创建作业</strong></div>
    <header class="heading"><div><p>NEW ASSIGNMENT</p><h1>创建作业</h1><span>{{ course?.name || '当前课程' }}</span></div><div class="step">1 <span>基本信息</span>　—　2 <span>评价分支</span></div></header>
    <div v-if="errorMessage" class="error-box">{{ errorMessage }}</div>
    <form class="form-card" @submit.prevent="submit"><section><div class="section-title"><h2>基本信息</h2><span>填写作业要求和提交截止时间</span></div><div class="form-grid"><label class="full">作业名称<input v-model.trim="form.title" maxlength="200" required placeholder="例如：需求分析" /></label><label class="full">作业说明<textarea v-model="form.description" maxlength="5000" placeholder="说明作业目标、提交要求和评分重点"></textarea></label><label>截止时间<input v-model="form.deadline" type="datetime-local" required /></label><label>标准团队人数<select v-model.number="form.standardGroupSize"><option :value="1">1 人</option><option :value="2">2 人</option><option :value="3">3 人</option><option :value="4">4 人</option></select></label><label>作业总分<input v-model.number="form.totalScore" type="number" min="1" max="100" required /></label></div></section><section><div class="section-title"><h2>评价分支</h2><span>权重总和必须为 100%</span></div><div v-for="(branch, index) in form.branches" :key="index" class="branch"><div class="branch-number">{{ index + 1 }}</div><div class="branch-fields"><input v-model.trim="branch.name" maxlength="255" required placeholder="分支名称，例如：需求完整性" /><input v-model="branch.description" maxlength="2000" placeholder="评价分支说明（可选）" /></div><div class="weight"><input v-model.number="branch.weightPercent" type="number" min="0" max="100" required /><span>%</span></div><button v-if="form.branches.length > 1" type="button" class="remove" @click="removeBranch(index)">删除</button></div><button type="button" class="add-branch" @click="addBranch">＋ 添加评价分支</button><div class="weight-total" :class="{ invalid: !validWeight }">当前权重总和：<strong>{{ weightTotal }}%</strong><span>{{ validWeight ? '配置正确' : '请调整为 100%' }}</span></div></section><footer><button type="button" class="cancel" @click="router.push(`/teacher/course/${courseId}/assignments`)">取消</button><button class="save" type="submit" :disabled="saving || !validWeight">{{ saving ? '创建中…' : '保存为草稿' }}</button></footer></form>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { createAssignment, getCourses } from '@/api/teacher'
import { getErrorMessage } from '@/api/response'
const route = useRoute(); const router = useRouter(); const courseId = route.params.courseId; const courses = ref([]); const saving = ref(false); const errorMessage = ref('')
const form = ref({ title: '', description: '', deadline: '', standardGroupSize: 4, totalScore: 100, branches: [{ name: '作业质量', description: '', weightPercent: 60 }, { name: '团队协作', description: '', weightPercent: 40 }] })
const course = computed(() => courses.value.find((item) => String(item.id) === String(courseId))); const weightTotal = computed(() => form.value.branches.reduce((sum, branch) => sum + Number(branch.weightPercent || 0), 0)); const validWeight = computed(() => Math.abs(weightTotal.value - 100) < 0.001)
const addBranch = () => form.value.branches.push({ name: '', description: '', weightPercent: 0 }); const removeBranch = (index) => form.value.branches.splice(index, 1)
const submit = async () => { if (!validWeight.value) return; saving.value = true; errorMessage.value = ''; try { await createAssignment(courseId, { ...form.value, deadline: new Date(form.value.deadline).toISOString().slice(0, 19), branches: form.value.branches.map(({ name, description, weightPercent }) => ({ name, description, weight: Number(weightPercent) / 100 })) }); ElMessage.success('作业草稿已创建'); router.push(`/teacher/course/${courseId}/assignments`) } catch (error) { errorMessage.value = getErrorMessage(error, '创建作业失败，请检查填写内容') } finally { saving.value = false } }
onMounted(async () => { try { courses.value = await getCourses() } catch (error) { errorMessage.value = getErrorMessage(error, '课程信息加载失败') } })
</script>
<style scoped>
.create-page{max-width:1000px;margin:0 auto}.breadcrumb{display:flex;gap:8px;margin-bottom:24px;color:#8795a6;font-size:14px}.breadcrumb button{padding:0;border:0;background:none;color:inherit;cursor:pointer}.breadcrumb strong{color:#263b53}.heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:26px}.heading p{margin:0 0 7px;color:#6bb58b;font-size:11px;letter-spacing:1.5px}.heading h1{margin:0 0 8px;color:#263b53;font-size:30px}.heading span{color:#8795a6;font-size:14px}.step{color:#6b9ed8;font-size:13px}.step span{color:#8795a6}.form-card{border:1px solid #e8edf2;border-radius:9px;background:#fff;box-shadow:0 2px 8px rgba(38,59,83,.05)}section{padding:24px;border-bottom:1px solid #edf1f4}.section-title{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:20px}.section-title h2{margin:0;color:#263b53;font-size:18px}.section-title span{color:#98a5b3;font-size:12px}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.form-grid label,.branch-fields{display:grid;gap:8px;color:#52657a;font-size:13px}.form-grid .full{grid-column:1/-1}.form-grid input,.form-grid textarea,.form-grid select,.branch input{box-sizing:border-box;width:100%;padding:10px 12px;border:1px solid #dbe3ea;border-radius:5px;outline:0;color:#334155;background:#fff;font:inherit}.form-grid textarea{min-height:105px;resize:vertical}.branch{display:flex;align-items:center;gap:12px;margin-bottom:13px}.branch-number{display:grid;width:28px;height:28px;place-items:center;border-radius:50%;color:#fff;background:#6b9ed8}.branch-fields{flex:1;grid-template-columns:1fr 1.5fr}.weight{display:flex;width:105px;align-items:center;gap:5px}.weight input{width:76px}.remove{border:0;color:#b42318;background:none;cursor:pointer}.add-branch{padding:9px 13px;border:1px dashed #aac5dc;border-radius:5px;color:#356798;background:#f8fbfd;cursor:pointer}.weight-total{margin-top:18px;color:#64748b;font-size:13px}.weight-total strong{margin-left:8px;color:#35845a}.weight-total span{margin-left:12px;color:#35845a}.weight-total.invalid strong,.weight-total.invalid span{color:#b42318}footer{display:flex;justify-content:flex-end;gap:12px;padding:18px 24px}.cancel,.save{padding:10px 20px;border:0;border-radius:5px;cursor:pointer}.cancel{color:#64748b;background:#f1f3f5}.save{color:#fff;background:#356798}.save:disabled{opacity:.5;cursor:not-allowed}.error-box{margin-bottom:16px;padding:13px;border-radius:6px;color:#b42318;background:#fff5f5}@media(max-width:720px){.heading{align-items:stretch;flex-direction:column;gap:14px}.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}.branch{align-items:stretch;flex-wrap:wrap}.branch-fields{width:calc(100% - 45px);flex:none;grid-template-columns:1fr}.weight{margin-left:40px}}
</style>
